content.arguments:
{"command":"try {
  $r = Invoke-RestMethod -Uri "https://api.bilibili.com/x/web-interface/ranking/v2?rid=0&type=all" -Headers @{ "User-Agent"="Mozilla/5.0"; "Referer"="https://www.bilibili.com" } -TimeoutSec 20
  $r.data.list | Select-Object -First 5 | ForEach-Object {
    [pscustomobject]@{ title=$_.title; tname=$_.tname; owner=$_.owner.name; view=$_.stat.view; bvid=$_.bvid }
  } | Format-List
} catch { "ERR: $($_.Exception.Message)" }","description":"Fetch Bilibili official ranking API top entries"}

